using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool state ---
var notes = new List<string>();

// --- Define tools ---
[Description("Search the web for information on a query. Returns relevant search result snippets.")]
string WebSearch(string query)
{
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. Wikipedia summary: {query} is a widely discussed topic with multiple facets covering technology, science, and society.
        2. Recent news: Experts highlight new developments in {query} during 2026, including breakthroughs in efficiency and accessibility.
        3. Research paper abstract: A 2025 study found that {query} adoption has grown 40% year-over-year, with significant implications for industry and policy.
        """;
}

[Description("Save a note to the research notebook for later use in the summary.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Build the AI chat client with tools ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Get topic from user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching \"{topic}\"...\n");

// --- Run the agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic using the 
        available tools, then produce a well-organized summary.

        Workflow:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Take notes on the key findings from each search.
        3. Once you have enough information, retrieve your notes and write a comprehensive summary.

        Be thorough but concise in your final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n=======================================");

